return {
	Name = "Rudie Bluebell",
	HolidaySkin = true,
	ApplySkin = function(p1) --[[ ApplySkin | Line: 6 ]]
		for k, v in pairs(p1:GetDescendants()) do
			if v:IsA("MeshPart") and v.Name ~= "Nose" then
				v.TextureID = "rbxassetid://93083268903119"
			end
		end

		local Nose = p1:WaitForChild("Nose", 5)

		if Nose then
			Nose.Color = Color3.new(0.360784, 0.615686, 1)
			Nose.Size = Vector3.new(Nose.Size.X, 0.4, Nose.Size.Z)

			for k, v in pairs(Nose:GetDescendants()) do
				if v:IsA("PointLight") or v:IsA("SpotLight") then
					v.Color = Color3.new(0.360784, 0.615686, 1)
				end
			end
		else
			warn("[RudieBlueBell] Nose part not found - skipping nose customization")
		end

		local HumanoidRootPart = p1:WaitForChild("HumanoidRootPart")

		for k, v in pairs(HumanoidRootPart:GetDescendants()) do
			if v:IsA("PointLight") or v:IsA("SpotLight") then
				v.Color = Color3.fromRGB(16, 77, 196)
			end
		end

		local Config = p1:WaitForChild("Config")

		Config:WaitForChild("HurtTexture").Texture = "rbxassetid://104051737949847"
		Config:WaitForChild("NormalTexture").Texture = "rbxassetid://93083268903119"
		Config:WaitForChild("BlinkTexture").Texture = "rbxassetid://120058044247679"

		local v1 = game.ServerStorage.SkinModelStorage[p1.Config.ModuleName.Value][script.Name][script.Name]:Clone()

		for k, v in pairs(v1:GetChildren()) do
			if v:IsA("MeshPart") and v.Name ~= "Nose" then
				local Weld = Instance.new("Weld")

				v.Parent = p1:WaitForChild(v.Name)
				Weld.Parent = v
				Weld.Part0 = v
				Weld.Part1 = p1:WaitForChild(v.Name)
				v.Anchored = false
				p1:WaitForChild(v.Name).Transparency = 1
			end
		end

		game:GetService("Debris"):AddItem(v1, 10)
	end
}